// Knight: aggressive skirmisher. Focus nearest enemy; retreat if low hp and outmatched.
const e = self.nearestEnemy();
if (self.hp < 25 && e && self.distanceTo(e) <= self.range + 1) {
  self.flee(e);
} else if (e) {
  if (self.distanceTo(e) <= self.range) self.attack(e);
  else self.moveTo(e.x, e.y);
} else {
  const b = self.enemyBase();
  if (b) self.moveTo(b.x, b.y);
  else self.hold();
}

// Ranger: ranged. Kite - if enemy in range, attack; if too close, back off; else advance.
const e = self.nearestEnemy();
if (!e) {
  const b = self.enemyBase();
  if (b) self.moveTo(b.x, b.y); else self.hold();
} else {
  const d = self.distanceTo(e);
  if (d <= self.range) self.attack(e);
  else if (d <= self.range + 1 && e.hp > self.hp) self.flee(e);
  else self.moveTo(e.x, e.y);
}

// Knight: engage nearby enemies; if a group of allies is present, push to enemy base; else return to rally.
const m = self.memory;
if (m.rx === undefined) { m.rx = 24; m.ry = 24; }
const e = self.nearestEnemy();
const allies = self.nearbyAllies().filter(u => u.type === 'knight' || u.type === 'ranger');
if (e && self.distanceTo(e) <= self.vision) {
  if (self.distanceTo(e) <= self.range) self.attack(e);
  else self.moveTo(e.x, e.y);
} else if (allies.length >= 2) {
  const b = self.enemyBase();
  if (b) self.moveTo(b.x, b.y); else self.hold();
} else {
  const d = Math.max(Math.abs(self.x - m.rx), Math.abs(self.y - m.ry));
  if (d > 1) self.moveTo(m.rx, m.ry);
  else self.hold();
}

