// Ranger: engage in vision (kite knights), else return to rally.
const m = self.memory;
if (m.rx === undefined) { m.rx = 25; m.ry = 24; }
const e = self.nearestEnemy();
if (e && self.distanceTo(e) <= self.vision) {
  const d = self.distanceTo(e);
  if (d <= self.range) self.attack(e);
  else if (d <= self.range + 1 && e.type === 'knight') self.flee(e);
  else self.moveTo(e.x, e.y);
} else {
  const d = Math.max(Math.abs(self.x - m.rx), Math.abs(self.y - m.ry));
  if (d > 3) self.moveTo(m.rx, m.ry);
  else self.hold();
}

// Knight: don't chase ranged units into open; defend near nexus.
const e = self.nearestEnemy();
if (e && self.distanceTo(e) <= self.range) {
  self.attack(e);
} else if (e && self.distanceTo(e) <= 2 && e.type !== 'ranger') {
  self.moveTo(e.x, e.y);
} else {
  // hold near nexus
  const b = self.myBase();
  if (b) {
    const d = Math.max(Math.abs(self.x - (b.x - 1)), Math.abs(self.y - (b.y - 2)));
    if (d > 3) self.moveTo(b.x - 1, b.y - 2); else self.hold();
  } else self.hold();
}
